using System.Collections.Generic;
using System.ComponentModel;
using System.Diagnostics;
using System.IO;
using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace SophonDownloader.Services;

public sealed class Aria2cProgressInfo
{
    public long BytesReceived { get; init; }
    public long? TotalBytes { get; init; }
    public double? Percent { get; init; }
    public long? SpeedBytesPerSecond { get; init; }
    public TimeSpan? Eta { get; init; }
}

public sealed class Aria2cDownloadException : IOException
{
    public int ExitCode { get; }

    public Aria2cDownloadException(int exitCode, string message) : base(message) => ExitCode = exitCode;
}

public sealed class Aria2c
{
    private const string Aria2cBase64 = """
    
    """;

    private readonly object _processLock = new();
    private Process? _process;

    private static readonly Regex ProgressRegex = new(
        @"(?<current>\d+(?:\.\d+)?)\s*(?<currentUnit>[KMGTPE]?i?B)\s*/\s*(?<total>\d+(?:\.\d+)?)\s*(?<totalUnit>[KMGTPE]?i?B)\s*\((?<percent>\d+(?:\.\d+)?)%\)",
        RegexOptions.Compiled | RegexOptions.IgnoreCase);

    private static readonly Regex SpeedRegex = new(
        @"DL:(?<speed>\d+(?:\.\d+)?)\s*(?<unit>[KMGTPE]?i?B)",
        RegexOptions.Compiled | RegexOptions.IgnoreCase);

    private static readonly Regex EtaRegex = new(
        @"ETA:(?<eta>[^\s\]\)]+)",
        RegexOptions.Compiled | RegexOptions.IgnoreCase);

    public string ExecutablePath => ExtractAria2c();

    public void Pause() => KillCurrentProcess();
    public void Cancel() => KillCurrentProcess();

    public static void KillAllProcesses()
    {
        foreach (Process process in Process.GetProcessesByName("aria2c"))
        {
            try
            {
                if (process.HasExited) continue;

                try { process.Kill(entireProcessTree: true); }
                catch
                {
                    try { process.Kill(); }
                    catch { }
                }

                try { process.WaitForExit(2000); }
                catch { }
            }
            catch { }
            finally { process.Dispose(); }
        }
    }

    public async Task<int> RunAsync(
        string url,
        string outputDirectory,
        string outputFileName,
        long existingBytes,
        Action<string>? outputLine,
        Action<Aria2cProgressInfo>? progress,
        CancellationToken ct,
        int maxConnectionsPerServer = 8,
        int split = 8,
        long speedLimitBytesPerSecond = 0,
        string logLevel = "notice",
        string? dnsServer = null,
        string proxyMode = "System",
        string? proxyHost = null,
        int proxyPort = 8080)
    {
        if (string.IsNullOrWhiteSpace(url))
            throw new ArgumentException("URL cannot be empty.", nameof(url));

        if (string.IsNullOrWhiteSpace(outputDirectory))
            throw new ArgumentException("Output directory cannot be empty.", nameof(outputDirectory));

        if (string.IsNullOrWhiteSpace(outputFileName))
            throw new ArgumentException("Output file name cannot be empty.", nameof(outputFileName));

        Directory.CreateDirectory(outputDirectory);

        string executable = ExtractAria2c();
        maxConnectionsPerServer = Math.Clamp(maxConnectionsPerServer, 1, 64);
        split = Math.Clamp(split, 1, 64);
        logLevel = logLevel?.Trim().ToLowerInvariant() switch
        {
            "trace" => "debug",
            "debug" => "debug",
            "warn" => "warn",
            "error" => "error",
            "fatal" => "error",
            _ => "notice"
        };

        var psi = new ProcessStartInfo
        {
            FileName = executable,
            WorkingDirectory = outputDirectory,
            UseShellExecute = false,
            CreateNoWindow = true,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            StandardOutputEncoding = Encoding.UTF8,
            StandardErrorEncoding = Encoding.UTF8
        };

        var arguments = new List<string>
        {
            "--continue=true",
            "--always-resume=true",
            $"--max-connection-per-server={maxConnectionsPerServer}",
            $"--split={split}",
            "--min-split-size=20M",
            "--file-allocation=none",
            "--summary-interval=1",
            "--show-console-readout=true",
            $"--console-log-level={logLevel}",
            "--connect-timeout=30",
            "--timeout=60",
            "--max-tries=10",
            "--retry-wait=3"
        };

        if (speedLimitBytesPerSecond > 0)
            arguments.Add($"--max-overall-download-limit={speedLimitBytesPerSecond}");

        if (!string.IsNullOrWhiteSpace(dnsServer))
            arguments.Add($"--dns-server={dnsServer.Trim()}");

        NetworkClient.AddAria2cProxyArguments(arguments, new AppSettings
        {
            ProxyMode = proxyMode,
            ProxyHost = proxyHost ?? string.Empty,
            ProxyPort = proxyPort
        }, url);

        arguments.AddRange(new[]
        {
            "--download-result=hide",
            "--auto-file-renaming=false",
            "--allow-overwrite=true",
            "--dir=" + outputDirectory,
            "--out=" + outputFileName,
            url
        });

        foreach (string argument in arguments)
            psi.ArgumentList.Add(argument);

        var process = new Process { StartInfo = psi, EnableRaisingEvents = true };

        lock (_processLock)
            _process = process;

        try
        {
            if (!process.Start())
                throw new InvalidOperationException("Failed to start aria2c.exe.");

            using var registration = ct.Register(static state =>
            {
                if (state is Aria2c aria2c)
                    aria2c.KillCurrentProcess();
            }, this);

            Task stdoutTask = ReadOutputAsync(process.StandardOutput, outputLine, progress);
            Task stderrTask = ReadOutputAsync(process.StandardError, outputLine, progress);
            Task exitTask = process.WaitForExitAsync();
            Task cancellationTask = Task.Delay(Timeout.InfiniteTimeSpan, ct);
            Task completedTask = await Task.WhenAny(exitTask, cancellationTask);

            if (completedTask == cancellationTask)
            {
                KillCurrentProcess();
                throw new OperationCanceledException(ct);
            }

            await exitTask;

            try { await Task.WhenAll(stdoutTask, stderrTask).WaitAsync(TimeSpan.FromMilliseconds(500)); }
            catch { }

            ct.ThrowIfCancellationRequested();
            return process.ExitCode;
        }
        finally
        {
            lock (_processLock)
            {
                if (ReferenceEquals(_process, process))
                    _process = null;
            }

            TryDisposeProcess(process);
        }
    }

    private static async Task ReadOutputAsync(
        StreamReader reader,
        Action<string>? outputLine,
        Action<Aria2cProgressInfo>? progress)
    {
        try
        {
            while (true)
            {
                string? line = await reader.ReadLineAsync();
                if (line is null) break;
                if (string.IsNullOrWhiteSpace(line)) continue;

                outputLine?.Invoke(line);

                if (TryParseProgress(line, out Aria2cProgressInfo info))
                    progress?.Invoke(info);
            }
        }
        catch { }
    }

    private static bool TryParseProgress(string line, out Aria2cProgressInfo info)
    {
        info = new Aria2cProgressInfo();

        Match sizeMatch = ProgressRegex.Match(line);
        Match speedMatch = SpeedRegex.Match(line);
        Match etaMatch = EtaRegex.Match(line);

        if (!sizeMatch.Success && !speedMatch.Success && !etaMatch.Success)
            return false;

        long? bytesReceived = null;
        long? totalBytes = null;
        double? percent = null;
        long? speed = null;
        TimeSpan? eta = null;

        if (sizeMatch.Success &&
            double.TryParse(sizeMatch.Groups["current"].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out double current) &&
            double.TryParse(sizeMatch.Groups["total"].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out double total) &&
            double.TryParse(sizeMatch.Groups["percent"].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out double pct))
        {
            bytesReceived = (long)ToBytes(current, sizeMatch.Groups["currentUnit"].Value);
            totalBytes = (long)ToBytes(total, sizeMatch.Groups["totalUnit"].Value);
            percent = Math.Clamp(pct, 0, 100);
        }

        if (speedMatch.Success &&
            double.TryParse(speedMatch.Groups["speed"].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out double speedValue))
            speed = (long)ToBytes(speedValue, speedMatch.Groups["unit"].Value);

        if (etaMatch.Success)
            eta = ParseEta(etaMatch.Groups["eta"].Value);

        info = new Aria2cProgressInfo
        {
            BytesReceived = bytesReceived ?? 0,
            TotalBytes = totalBytes,
            Percent = percent,
            SpeedBytesPerSecond = speed,
            Eta = eta
        };

        return true;
    }

    private static TimeSpan? ParseEta(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return null;

        value = value.Trim();

        if (value.Equals("UNKNOWN", StringComparison.OrdinalIgnoreCase))
            return null;

        if (TimeSpan.TryParse(value, CultureInfo.InvariantCulture, out TimeSpan time))
            return time;

        Match match = Regex.Match(value, @"^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$", RegexOptions.IgnoreCase);
        if (!match.Success) return null;

        int hours = match.Groups[1].Success ? int.Parse(match.Groups[1].Value, CultureInfo.InvariantCulture) : 0;
        int minutes = match.Groups[2].Success ? int.Parse(match.Groups[2].Value, CultureInfo.InvariantCulture) : 0;
        int seconds = match.Groups[3].Success ? int.Parse(match.Groups[3].Value, CultureInfo.InvariantCulture) : 0;

        return new TimeSpan(hours, minutes, seconds);
    }

    private static double ToBytes(double value, string unit) =>
        unit.ToUpperInvariant() switch
        {
            "B" => value,
            "KB" => value * 1000d,
            "MB" => value * 1000d * 1000d,
            "GB" => value * 1000d * 1000d * 1000d,
            "KIB" => value * 1024d,
            "MIB" => value * 1024d * 1024d,
            "GIB" => value * 1024d * 1024d * 1024d,
            _ => value
        };

    private void KillCurrentProcess()
    {
        Process? process;

        lock (_processLock)
            process = _process;

        if (process is null) return;

        try
        {
            if (!process.HasExited)
                process.Kill(entireProcessTree: true);
        }
        catch (InvalidOperationException) { }
        catch (Win32Exception) { }
    }

    private static void TryDisposeProcess(Process process)
    {
        try { process.Dispose(); }
        catch { }
    }

    private static string ExtractAria2c()
    {
        string tempDirectory = Path.Combine(Path.GetTempPath(), "SophonDownloader");
        Directory.CreateDirectory(tempDirectory);

        string tempPath = Path.Combine(tempDirectory, "aria2c.exe");
        if (File.Exists(tempPath)) return tempPath;

        if (string.IsNullOrWhiteSpace(Aria2cBase64))
            throw new InvalidOperationException("Embedded aria2c.exe Base64 is missing.");

        try
        {
            string base64 = Regex.Replace(Aria2cBase64, @"\s+", "");
            byte[] bytes = Convert.FromBase64String(base64);

            File.WriteAllBytes(tempPath, bytes);
            return tempPath;
        }
        catch (FormatException ex)
        {
            throw new InvalidOperationException("The embedded aria2c Base64 payload is invalid.", ex);
        }
        catch (IOException ex)
        {
            throw new InvalidOperationException($"Failed to extract aria2c.exe to:\n{tempPath}", ex);
        }
    }
}
